                ['p', 'Cofondateur du Front populaire ivoirien, il en devient l’une des figures historiques et reste fidèle à la ligne de Laurent Gbagbo.'],
                ['h2', 'Ministre des Affaires étrangères'],
                ['p', 'Il est ministre des Affaires étrangères d’octobre 2000 à mars 2003, au début de la présidence de Laurent Gbagbo. À sa mort en 2018, il préside une tendance pro-Gbagbo au sein du FPI.'],
