            'blocks' => [
                ['p', 'Jean-Jacques Béchio, né le 22 août 1949 à Grand-Bassam et mort le 12 février 2018 à Abidjan, est un homme politique ivoirien. Diplômé en droit de l’université d’Abidjan et de l’ENA, il est secrétaire général du Mouvement des étudiants et élèves de Côte d’Ivoire au début des années 1970.'],
                ['h2', 'Le diplomate'],
                ['p', 'Il choisit la carrière diplomatique et se spécialise sur le Proche et le Moyen-Orient. Premier conseiller d’ambassade à Téhéran jusqu’au renversement du chah, il est ensuite en poste au Pakistan avant de revenir en Côte d’Ivoire à la fin des années 1970.'],
                ['h2', 'Le ministre de la rigueur'],
                ['p', 'Il entre au gouvernement en 1983, à 34 ans, comme ministre de la Fonction publique et porte-parole du gouvernement. Il est le principal artisan de la restructuration de l’administration et mène une politique de rigueur contre l’absentéisme et la corruption.'],
