            'summary' => 'Ingénieur et homme politique ivoirien né en 1965, Claude Isaac Dé a été ministre de la Construction, puis de l’Économie numérique et de la Poste.',
            'blocks' => [
                ['p', 'Claude Isaac Dé, né le 30 septembre 1965 à Abidjan, est un homme politique ivoirien originaire de la région des Grands Ponts. Ingénieur des travaux publics diplômé de l’Institut national polytechnique Félix Houphouët-Boigny en 1988, il fait carrière à la Banque mondiale et au sein de l’administration ivoirienne.'],
                ['h2', 'Les grands travaux'],
                ['p', 'Conseiller spécial du Premier ministre chargé de la reconstruction de 2003 à 2005, puis conseiller à la présidence chargé des infrastructures, il est nommé ministre de la Construction, du Logement, de l’Assainissement et de l’Urbanisme le 11 janvier 2017.'],
                ['h2', 'Le numérique et les Grands Ponts'],
                ['p', 'Le 10 juillet 2018, il devient ministre de l’Économie numérique et de la Poste, puis ministre auprès du Premier ministre chargé de la coordination des Grands Ponts de septembre 2019 au 30 juillet 2020. Il quitte le RHDP et retourne au PDCI-RDA en mai 2024.'],
            ],
