            'occupations' => ['Écrivain', 'Enseignant'],
            'summary' => "Écrivain ivoirien (1911-1989), Bernard Dadier a écrit le roman pionnier Climbié (1956), l'un des premiers romans africains d'expression française.",
            'blocks' => [
                ['p', "Bernard Dadier, né en 1911 à Aboisso, est l'un des pères de la littérature ivoirienne. Enseignant, il écrit pour défendre la culture africaine et raconter le monde de l'école coloniale."],
                ['h2', 'Climbié, le premier roman'],
                ['p', "Publié en 1956, Climbié est l'un des tous premiers romans africains écrits en français. Il suit la scolarité d'un enfant entre l'école villageoise et les grands établissements, et interroge déjà la relation entre tradition et modernité."],
                ['h2', 'Le passeur de culture'],
                ['p', "Dadier consacre sa vie à la littérature et à l'enseignement, participant aux revues africaines et aux institutions culturelles. Il meurt à Dakar en 1989, après avoir vu Climbié devenir un texte de référence des lycées francophones."],
