                ['p', 'Il publie en 2003 le roman Les Prisonniers de la haine, puis Robert et les catapila en 2005, Nègreries en 2007, Les catapila, ces ingrats en 2009 et Chroniques afro-sarcastiques en 2011. Sa biographie d’Edem Kodjo, un homme, un destin, lui vaut le Grand prix littéraire d’Afrique noire en 2012.'],
