            'summary' => 'Femme de lettres ivoirienne (1937-2007), Simone Kaya est l’une des pionnières du roman féminin ivoirien.',
            'blocks' => [
                ['p', 'Simone Kaya, née le 11 février 1937 à Bouaflé et morte le 7 juin 2007 à Ouagadougou, est une femme de lettres ivoirienne de langue française. Elle est la première infirmière d’État de Côte d’Ivoire et la première directrice de l’Institut national de la formation sociale.'],
                ['h2', 'Les Danseuses d’Impé-eya'],
                ['p', 'Elle publie en 1976 Les Danseuses d’Impé-eya. Jeunes filles à Abidjan, roman autobiographique préfacé par Cheikh Hamidou Kane, puis Le Prix d’une vie en 1984. Ses récits racontent une tranche de sa vie et l’histoire d’une génération d’Ivoiriennes.'],
                ['h2', 'Une pionnière'],
                ['p', 'Première femme à entrer dans la littérature ivoirienne, elle occupe une place particulière dans l’histoire littéraire du pays. Son œuvre se situe à la charnière de l’ère coloniale et des États indépendants.'],
            ],
            'bibliography' => [
                ['title' => 'Simone Kaya', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Simone_Kaya'],
            ],
        ],
        [
            'slug' => 'regina-yaou',
            'name' => 'Regina Yaou',
            'fullName' => 'Regina Yaou',
            'birth' => '1955',
            'birthPlace' => 'Dabou',
            'death' => '2017',
            'deathPlace' => 'Abidjan',
            'occupations' => ['Romancière'],
            'summary' => 'Romancière ivoirienne (1955-2017), Regina Yaou a raconté le quotidien et le statut des femmes, du roman littéraire aux collections sentimentales.',
            'blocks' => [
                ['p', 'Régina Yaou, née le 10 juillet 1955 à Dabou et morte le 4 novembre 2017 à Abidjan, est une romancière ivoirienne. Élevée par sa tante sage-femme dans une famille passionnée de lecture, elle écrit ses premiers poèmes entre 12 et 14 ans.'],
                ['h2', 'Lezou Marie et La Révolte d’Affiba'],
                ['p', 'Après un prix littéraire en 1977 et des études à Tours puis à Abidjan, elle publie son premier roman, Lezou Marie ou les écueils de la vie, en 1982, suivi de La Révolte d’Affiba en 1985. Ses œuvres abordent la violence domestique, l’infidélité, la maternité et la stérilité.'],
                ['h2', 'Une romancière reconnue'],
                ['p', 'À partir de la fin des années 1990, elle publie aussi sous pseudonymes dans la collection Adoras. Elle séjourne aux États-Unis comme consultante et conférencière, reçoit le Prix national d’excellence pour la littérature en 2014 et est l’auteure à l’honneur du Salon international du livre d’Abidjan en 2016.'],
            ],
            'bibliography' => [
                ['title' => 'Regina Yaou', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Regina_Yaou'],
            ],
        ],
        [
            'slug' => 'anne-marie-adiaffi',
            'name' => 'Anne-Marie Adiaffi',
            'fullName' => 'Anne-Marie Adiaffi',
            'birth' => '1951',
            'birthPlace' => 'Abengourou',
            'death' => '1994',
            'deathPlace' => null,
            'occupations' => ['Écrivaine'],
            'summary' => 'Écrivaine ivoirienne (1951-1994), Anne-Marie Adiaffi s’est fait connaître en 1983 avec le roman Une vie hypothéquée.',
            'blocks' => [
                ['p', 'Anne-Marie Adiaffi, née le 21 mars 1951 à Abengourou et morte en 1994 à Abidjan, est une écrivaine ivoirienne. Elle suit sa scolarité primaire et secondaire en Côte d’Ivoire puis à Marseille, obtient un diplôme de secrétaire bilingue à Dakar et travaille comme secrétaire dans une banque avant de rejoindre les Nouvelles Éditions Africaines d’Abidjan en 1983.'],
                ['h2', 'Une vie hypothéquée'],
                ['p', 'Elle publie en 1983 Une vie hypothéquée aux Nouvelles Éditions Africaines d’Abidjan, où elle travaille depuis la même année. Le roman est une satire de la famille traditionnelle agni : Yah, promise avant sa naissance à Béhira, un homme de 55 ans déjà marié et père de famille, découvre la vérité à 15 ans et s’enfuit à Abidjan avant d’être ramenée vers ce mariage.'],
                ['h2', 'Une parole pionnière'],
                ['p', 'L’ouvrage est salué pour sa satire et sa dimension féministe : il compte parmi les premiers textes d’autrices ivoiriennes à critiquer aussi explicitement les contraintes imposées aux femmes par la tradition. Anne-Marie Adiaffi meurt à Abidjan en 1994 en laissant ce roman, étudié comme un jalon de la littérature ivoirienne.'],
            ],
            'bibliography' => [
                ['title' => 'Anne-Marie Adiaffi', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Anne-Marie_Adiaffi'],
            ],
        ],
        [
            'slug' => 'germain-coffi-gadeau',
            'name' => 'Germain Coffi Gadeau',
            'fullName' => 'Germain Coffi Gadeau',
            'birth' => '1913',
            'birthPlace' => 'Gbomizambo (Tiébissou)',
            'death' => '2000',
            'deathPlace' => null,
            'occupations' => ['Écrivain', 'Homme politique'],
            'summary' => 'Écrivain et homme politique ivoirien (1913-2000), Germain Coffi Gadeau a cofondé le Théâtre indigène de Côte d’Ivoire en 1938.',
            'blocks' => [
                ['p', 'Germain Coffi Gadeau, né en 1913 à Gbomizambo, dans la sous-préfecture de Tiébissou, et mort le 18 août 2000, est un écrivain et homme politique ivoirien, auteur de pièces de théâtre.'],
                ['h2', 'Le théâtre'],
                ['p', 'Avec François-Joseph Amon d’Aby, il fonde en 1938 le Théâtre indigène de Côte d’Ivoire. Cette initiative compte parmi les premières tentatives d’un théâtre ivoirien écrit et joué par des auteurs du pays.'],
                ['h2', 'L’homme politique'],
                ['p', 'Il mène en parallèle une carrière politique et occupe notamment le ministère de la Justice au début des années 1960. Son parcours illustre le lien entre les premiers écrivains ivoiriens et la construction de l’État indépendant.'],
            ],
            'bibliography' => [
                ['title' => 'Germain Coffi Gadeau', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Germain_Coffi_Gadeau'],
            ],
        ],
