            'summary' => 'Écrivain ivoirien (1913-2007), François-Joseph Amon d’Aby a cofondé le Théâtre indigène de Côte d’Ivoire et dirigé les archives nationales.',
            'blocks' => [
                ['p', 'François-Joseph Amon d’Aby, également connu sous le nom d’Amon Koutouan, né le 17 juillet 1913 à Aby, dans le Sud-Comoé, et mort le 10 janvier 2007, est un écrivain ivoirien d’expression française.'],
                ['h2', 'Le théâtre et les archives'],
                ['p', 'Avec Germain Coffi Gadeau, il fonde en 1938 le Théâtre indigène de Côte d’Ivoire. Il est chef du service des archives de Côte d’Ivoire et le premier Ivoirien à accéder au poste d’inspecteur des affaires administratives, en 1961.'],
                ['h2', 'Une œuvre de pionnier'],
                ['p', 'Dramaturge et essayiste, il appartient à la première génération d’auteurs ivoiriens publiés en français. Son travail de mémoire administrative accompagne son écriture théâtrale.'],
            ],
            'bibliography' => [
