            'occupations' => ['Poète', 'Romancier', 'Dramaturge', 'Diplomate'],
            'summary' => 'Poète, romancier et diplomate ivoirien (1920-2004), Anoma Kanié est l’un des pionniers de la littérature ivoirienne d’expression française.',
            'blocks' => [
                ['p', 'Léon Maurice Anoma Kanié, né le 17 juillet 1920 à Grand-Bassam et mort le 7 juillet 2004 à Abidjan, est un poète, romancier, dramaturge, conteur, essayiste, critique littéraire, journaliste et diplomate ivoirien. Il est le fils du syndicaliste et homme d’État Joseph Anoma.'],
                ['h2', 'Les Eaux du Comoé'],
                ['p', 'Admirateur de José-Maria de Heredia et de Charles Baudelaire, il publie à Paris en 1951 le recueil Les Eaux du Comoé, puis un roman de mœurs, Les Malheurs d’Amangoua. Il compte parmi les pionniers de la littérature ivoirienne aux côtés de Bernard Dadié, Michel Thew Adjié, Bertin Doutéo et Aké Loba.'],
                ['h2', 'Le journaliste et le diplomate'],
                ['p', 'Attaché de presse de Félix Houphouët-Boigny dès les premières années de l’indépendance, il collabore à de nombreux périodiques internationaux. Ambassadeur à Chypre puis en Israël, il est membre de la Société des gens de lettres et du Pen Club international.'],
            ],
            'bibliography' => [
                ['title' => 'Anoma Kanié', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Anoma_Kani%C3%A9'],
            ],
        ],
