            'blocks' => [
                ['p', 'Denis Oussou-Essui, né le 25 juillet 1934 à Koliakro et mort le 6 mai 2010 à Abidjan, est un journaliste, écrivain et homme politique ivoirien.'],
                ['h2', 'La télévision et l’agence'],
                ['p', 'Il présente le journal télévisé de la RTI dans les années 1970, puis devient directeur général de l’Agence ivoirienne de presse de 1978 à 1980. Son parcours de journaliste le place au cœur de l’information publique ivoirienne.'],
                ['h2', 'Le député'],
                ['p', 'Il est élu député PDCI de Bocanda en 1980, 1985 et 1990. Son œuvre écrite accompagne une carrière politique ancrée dans le centre du pays.'],
