            'occupations' => ['Écrivain', 'Réalisateur', 'Scénariste'],
            'summary' => 'Écrivain, réalisateur et universitaire ivoirien (1956-2012), Kitia Touré a travaillé pour le cinéma et l’enseignement.',
            'blocks' => [
                ['p', 'Kitia Touré, né en 1956 à Ayamé, dans la région d’Aboisso, et mort dans la nuit du 18 au 19 décembre 2012, est un écrivain, scénariste et réalisateur ivoirien. Il est titulaire d’un doctorat de troisième cycle de lettres, littérature moderne, à la Sorbonne (Paris IV), et d’un DEA d’études cinématographiques et théâtrales à Paris I.'],
                ['h2', 'L’université et le cinéma'],
                ['p', 'Il est professeur assistant chargé de l’audiovisuel à l’Institut national supérieur des arts et de l’action culturelle (INSAC) et à l’UFR Information, communication et arts de l’université d’Abidjan-Cocody, où il enseigne l’économie du cinéma, le multimédia et l’Internet. Il dirige la Compagnie ivoirienne du cinéma et de l’audiovisuel (CIVCA) de 1994 à 2000.'],
                ['h2', 'Prix Noma et cinéma'],
                ['p', 'Boursier du Centre national du livre en 1996, il reçoit la même année le prix Noma pour Destins parallèles, roman publié en 1995 aux Nouvelles Éditions Ivoiriennes. Il est aussi l’auteur de L’Arbre et le fruit (1979), du Corbillard (1987), prix de la meilleure nouvelle en langue française 1980, et de Chez Tantie (1984). Son long métrage Comédie exotique (1985) est primé à Carthage et au Canada, et Maman je veux vivre obtient le prix UNICEF au FESPACO.'],
            ],
            'bibliography' => [
                ['title' => 'Kitia Touré', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Kitia_Tour%C3%A9'],
            ],
        ],
