                ['h2', 'Un regard sur la Suisse'],
                ['p', 'Il est régulièrement invité par les médias de Suisse alémanique et romande pour ses analyses sur la cohabitation culturelle, la lutte contre les discriminations et l’intégration des étrangers.'],
