            'blocks' => [
                ['p', 'Yaya Diomandé, né en 1990, vit à Abidjan. Il est diplômé en transport-logistique, en finance-comptabilité et en droit privé, et a travaillé comme traducteur-interprète avant de créer le journal en ligne Investissements+.'],
                ['h2', 'Abobo Marley'],
                ['p', 'Son premier roman, Abobo Marley, paraît en 2020 aux éditions JC Lattès. Il suit Moussa, « balanceur » sur un gbaka entre Abobo et Adjamé, qui rêve de rejoindre l’Europe. Le livre est le premier lauréat du prix Voix d’Afriques, décerné par RFI et JC Lattès parmi 372 manuscrits, avec un jury présidé par Abdourahman A. Waberi.'],
                ['h2', 'Le travail d’écriture'],
                ['p', 'Yaya Diomandé a travaillé cinq ans sur ce roman avant de le faire publier. Son parcours associe l’écriture, la traduction et le journalisme économique.'],
