            'summary' => 'Bibliothécaire et écrivain ivoirien né en 1966, Sidney Karams a fondé le Romandroom, espace de lecture et d’échanges littéraires à Abidjan.',
            'blocks' => [
                ['p', 'Sidney Karams, de son vrai nom Gbané Karamoko Sidiki, né le 20 décembre 1966 à Agboville, est un bibliothécaire et écrivain ivoirien.'],
                ['h2', 'Le Romandroom'],
                ['p', 'Il fonde en 2003 le Romandroom, bibliothèque sociale installée à Treichville, cité Arras 1, à Abidjan. Présentée comme la première bibliothèque sociale de Côte d’Ivoire, elle favorise la lecture auprès des enfants et des adultes et accueille des séances de lecture et de poésie.'],
                ['h2', 'Promouvoir la lecture'],
                ['p', 'Le Romandroom organise aussi des rencontres avec des écrivains et des actions de sensibilisation des parents à la lecture. Sidney Karams y intervient comme animateur culturel et responsable de la structure.'],
            ],
