            'birth' => '1960',
            'birthPlace' => 'Agboville',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Journaliste', 'Écrivain'],
            'summary' => 'Journaliste et écrivain franco-ivoirien né en 1960, Serge Bilé a reçu le prix Ebony en 1995 et publié plusieurs essais sur la mémoire de la déportation.',
            'blocks' => [
                ['p', 'Serge Bilé, né le 26 juin 1960 à Agboville, est un journaliste et écrivain franco-ivoirien. Diplômé de l’École supérieure de journalisme de Lille en 1988, il travaille pour France 3, Fraternité Matin, Africa et TV5. Après une maîtrise, il devient journaliste à RFO Paris en 1993, puis passe par RFO Guyane et RFO Martinique, où il présente le journal télévisé de juillet 1994 à août 2019.'],
                ['h2', 'Le passeur de mémoires'],
                ['p', 'En 1994, il fonde Akwaba, une association interculturelle ivoirienne et martiniquaise destinée à créer des liens entre Africains et Antillais. L’Union nationale des journalistes de Côte d’Ivoire lui décerne le prix Ebony en 1995. Passionné de musique, il écrit pour de nombreux artistes et signe Nouveau monde, une chanson distinguée par la Sacem et enregistrée au profit de l’Unicef.'],
                ['p', 'Dix ans après son documentaire Noirs dans les camps nazis (1995), il publie un essai du même nom, vivement critiqué par plusieurs historiens pour ses erreurs et son manque de rigueur, mais soutenu par d’autres chercheurs ; France Télévisions sera condamné pour avoir faussé l’attribution d’un prix à cet ouvrage. Il est aussi l’auteur de Sur le dos des hippopotames et de Boni : la naissance d’un peuple (2018).'],
            ],
            'bibliography' => [
                ['title' => 'Serge Bilé', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Serge_Bil%C3%A9'],
            ],
        ],
        [
            'slug' => 'ahmadou-kourouma',
            'name' => 'Ahmadou Kourouma',
            'fullName' => 'Ahmadou Kourouma',
            'birth' => '1927',
            'birthPlace' => 'Boundiali',
            'death' => '2003',
            'deathPlace' => 'Bron (France)',
            'occupations' => ['Écrivain'],
            'summary' => 'Écrivain ivoirien (1927-2003), Ahmadou Kourouma a renouvelé le roman africain francophone et reçu le prix Renaudot en 2000 pour Allah n’est pas obligé.',
            'blocks' => [
                ['p', 'Ahmadou Kourouma, né le 24 novembre 1927 à Boundiali et mort le 11 décembre 2003 à Bron, est un écrivain ivoirien d’ethnie malinké. Son père est un marchand de noix de kola et il vit une partie de son enfance à Togobala, en Guinée, cadre de son premier roman. Élève à l’école rurale de Boundiali à partir de 1935, puis à Korhogo, Bingerville et Bamako, il est renvoyé de l’école technique supérieure pour avoir conduit des mouvements estudiantins et rentre en Côte d’Ivoire comme tirailleur à Bouaké.'],
                ['h2', 'Une œuvre de rupture'],
                ['p', 'Son premier roman, Les Soleils des indépendances, paraît en 1968 aux Presses de l’université de Montréal, puis au Seuil en 1970 ; il obtient le prix Maillé-Latour-Landry de l’Académie française en 1970. Monnè, outrages et défis reçoit le Grand prix littéraire d’Afrique noire en 1990, et En attendant le vote des bêtes sauvages le prix du Livre Inter en 1998. Son quatrième roman, Allah n’est pas obligé, publié en 2000, raconte le destin d’un enfant soldat et remporte le prix Renaudot, le prix Goncourt des lycéens et le prix Amerigo-Vespucci ; la même année, il reçoit le grand prix Jean-Giono pour l’ensemble de son œuvre.'],
                ['h2', 'La voix de la paix'],
                ['p', 'Lorsque la guerre civile éclate en Côte d’Ivoire, il prend position contre l’ivoirité et pour le retour de la paix. Il meurt à Bron en 2003, alors qu’il travaille à Quand on refuse on dit non, suite d’Allah n’est pas obligé publiée à titre posthume en 2004. Sa dépouille est transférée de Lyon en Côte d’Ivoire en 2014. Un prix littéraire décerné au Salon du livre de Genève porte son nom depuis 2004.'],
            ],
            'bibliography' => [
                ['title' => 'Ahmadou Kourouma', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Ahmadou_Kourouma'],
            ],
        ],
