            'occupations' => ['Dramaturge', 'Comédien', 'Metteur en scène'],
            'summary' => 'Acteur, metteur en scène et dramaturge ivoirien né en 1962, Fargass Assandé a fondé le N’Zassa Théâtre et reçu le prix d’interprétation du FESPACO 2015.',
            'blocks' => [
                ['p', 'Fargass Assandé, né le 11 mars 1962 à Bongouanou, est un acteur, metteur en scène et dramaturge ivoirien. En 1985, il fonde à Abidjan, avec Acho Weyer et Wassa Casimir, le N’Zassa Théâtre. Il est ensuite assistant à la mise en scène de plusieurs spectacles, dont Seins fermes, cheveux gris de Diallo Amadou, Les Enchaînés de Rémi Médou N’Vomo, Le Caméléon de Patrice N. Penda et Les Vautours de Dialama.'],
                ['h2', 'La scène et le festival'],
                ['p', 'Il met en scène de nombreuses pièces, notamment au Festival international de théâtre pour le développement, au Burkina Faso, et aux Francophonies de Limoges. Il présente Quartett d’Heiner Müller à Ouagadougou puis à la Comédie de Caen. En 2014, il interprète Estragon aux côtés de Michel Bohiri, qui joue Vladimir, dans une mise en scène d’En attendant Godot de Samuel Beckett dirigée par Jean Lambert-wild, Lorenzo Malaguerra et Marcel Bozonnet, créée à Caen puis présentée en France et en Suisse.'],
                ['h2', 'Le cinéma et Lupin'],
                ['p', 'Au cinéma, il apparaît dans Wariko, le gros lot de Kramo-Lanciné Fadika, puis travaille avec Henri Duparc sur Je m’appelle Fargass, dont il est aussi scénariste, et sur Caramel. Il tient le rôle de Blackshouam dans L’Œil du cyclone de Sékou Traoré, qui lui vaut le prix de la meilleure interprétation masculine au FESPACO en 2015. Il joue ensuite Babakar, le père d’Omar Sy, dans la série Lupin.'],
            ],
            'bibliography' => [
                ['title' => 'Fargass Assandé', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Fargass_Assand%C3%A9'],
            ],
        ],
        [
            'slug' => 'timite-bassori',
            'name' => 'Timité Bassori',
            'fullName' => 'Timité Bassori',
            'birth' => '1933',
            'birthPlace' => 'Aboisso',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Écrivain', 'Cinéaste', 'Comédien'],
            'summary' => 'Écrivain, cinéaste et comédien ivoirien né en 1933, Timité Bassori est considéré comme le père du cinéma ivoirien.',
            'blocks' => [
                ['p', 'Timité Bassori, né le 30 décembre 1933 à Aboisso, est un écrivain, cinéaste et acteur ivoirien, considéré comme le père du cinéma ivoirien. Il arrive en France en septembre 1956 et s’inscrit au Cours Simon pour apprendre le théâtre, en vue de devenir metteur en scène.'],
                ['h2', 'Le théâtre et le cinéma'],
                ['p', 'Avec trois autres jeunes comédiens noirs, Sarah Maldoror, Toto Bissainthe et Samba Ababakar, il monte au théâtre Huis Clos de Sartre. Rejoints par Robert Liensol, ils forment en 1958 la compagnie des Griots. Il étudie ensuite le cinéma à l’IDHEC, à Paris, et intègre quelque temps plus tard la télévision française. En 1964, il réalise le court métrage Sur la dune de la solitude, puis, en 1969, La femme au couteau, premier long métrage de fiction de Côte d’Ivoire.'],
                ['h2', 'L’institution'],
                ['p', 'Il a été directeur de la Société ivoirienne de cinéma et est l’auteur de plusieurs ouvrages.'],
            ],
            'bibliography' => [
                ['title' => 'Timité Bassori', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Timit%C3%A9_Bassori'],
            ],
        ],
        [
            'slug' => 'tiburce-koffi',
            'name' => 'Tiburce Koffi',
            'fullName' => 'Tiburce Jules Koffi',
            'birth' => '1955',
            'birthPlace' => 'Bouaké',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Écrivain', 'Dramaturge', 'Journaliste'],
            'summary' => 'Écrivain, dramaturge et journaliste ivoirien né en 1955, Tiburce Koffi est une voix engagée de la scène culturelle et a dirigé le Palais de la Culture de Treichville.',
            'blocks' => [
                ['p', 'Tiburce Jules Koffi, né le 12 avril 1955 à Bouaké, est un écrivain, dramaturge, journaliste, chroniqueur et homme politique ivoirien. Après des études supérieures en lettres modernes, il enseigne avant de rejoindre le journalisme et de collaborer avec plusieurs journaux ivoiriens de premier plan.'],
                ['h2', 'Le théâtre et la critique'],
                ['p', 'Il se fait connaître par ses prises de position tranchées, ses chroniques engagées et ses pièces à portée sociale et politique, jouées sur de nombreuses scènes ivoiriennes et africaines. Sa plume, à la fois critique et poétique, aborde les réalités contemporaines de l’Afrique, la gouvernance, les inégalités et la condition humaine.'],
                ['h2', 'L’institution culturelle'],
                ['p', 'Il occupe des fonctions de direction dans des institutions culturelles majeures, notamment comme directeur général du Palais de la Culture de Treichville, et devient conseiller spécial chargé de la culture auprès du président de la République. En août 2026, il reçoit le prix d’excellence dans la catégorie littérature.'],
            ],
            'bibliography' => [
                ['title' => 'Tiburce Koffi', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Tiburce_Koffi'],
            ],
        ],
