            'summary' => 'Écrivain et ingénieur culturel ivoirien né en 1968, Alain Tailly a dirigé le BURIDA et le Centre national des arts et de la culture.',
            'blocks' => [
                ['p', 'Alain Tailly, né le 12 juin 1968 à Abidjan, est docteur ès lettres et ingénieur culturel. Artiste pluriel — écrivain, poète, conteur, dramaturge, comédien, metteur en scène et acteur de cinéma —, il est reconnu pour ses contributions à la structuration du secteur culturel ivoirien.'],
                ['h2', 'L’administrateur culturel'],
                ['p', 'Diplômé en ingénierie culturelle en France, il coordonne le Programme de soutien aux initiatives culturelles décentralisées financé par l’Union européenne, dirige le Bureau ivoirien du droit d’auteur (BURIDA) entre 2001 et 2002, puis devient conseiller technique chargé des affaires culturelles et artistiques et directeur de cabinet adjoint au ministère de la Culture et de la Francophonie. Il dirige le Centre national des arts et de la culture (CNAC) de 2012 à 2017.'],
                ['h2', 'La poésie musicale'],
                ['p', 'Il est également un promoteur du slam en Côte d’Ivoire et mène une carrière de poésie musicale : son premier album, Western Blues, sorti en 2010, évoque la détresse de l’ouest ivoirien après les crises, et son second, Femme, mon Héroïne, paru en 2013, rend hommage à la femme, à la famille et à la société. Depuis 2021, il se fait aussi appeler Tailly Glôhi.'],
            ],
            'bibliography' => [
                ['title' => 'Alain Tailly', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Alain_Tailly'],
            ],
        ],
