                ['p', 'Assamala Amoi, née le 17 octobre 1960 à Paris, est une écrivaine d’origine ivoirienne, venant du sud de la Côte d’Ivoire. Elle vit en France durant ses premières années, puis rentre en Côte d’Ivoire avec ses parents en 1966, où elle effectue sa scolarité et ses études du primaire au supérieur. Elle obtient une maîtrise en littérature britannique.'],
                ['h2', 'La littérature de jeunesse'],
                ['p', 'Autrice de nouvelles, de poésie et de littérature pour la jeunesse, elle reçoit le prix Jeanne de Cavally le 28 avril 2026 pour son ouvrage Trésor perdu dans la ville, lors de l’ouverture du 16e Salon international du livre d’Abidjan.'],
