            'blocks' => [
                ['p', 'Mahoua Soumahoro, dite Mahoua S. Bakayoko, née le 6 mai 1969 à Abidjan, est une écrivaine ivoirienne. Après ses études primaires et secondaires, elle obtient son baccalauréat au lycée Mamie Adjoua de Yamoussoukro, puis s’inscrit à l’université d’Abidjan en faculté de lettres modernes.'],
                ['h2', 'Une reconnaissance institutionnelle'],
                ['p', 'À l’occasion du 25e anniversaire de la Chaire UNESCO de la culture de la paix à Abidjan, elle est honorée comme ambassadrice de la culture de la paix. Elle est également récipiendaire du 2e prix d’excellence Alassane Ouattara dans la catégorie littérature pour l’édition 2023.'],
            ],
            'bibliography' => [
