            'occupations' => ['Écrivaine', 'Réalisatrice', 'Scénariste'],
            'summary' => 'Réalisatrice, scénariste et écrivaine franco-ivoirienne née en 1972, Isabelle Boni-Claverie a publié La Grande Dévoreuse et réalisé Trop noire pour être Française ?.',
            'blocks' => [
                ['p', 'Isabelle Boni-Claverie, née le 27 février 1972 à Tiassalé, est une réalisatrice, scénariste et écrivaine franco-ivoirienne. Elle est la nièce de Danièle Boni-Claverie, ancienne ministre de la Communication, et la petite-fille d’Alphonse Boni, magistrat et ministre de la Justice de la Première République.'],
                ['h2', 'L’écriture et le cinéma'],
                ['p', 'Son roman La Grande Dévoreuse, écrit à 17 ans, est distingué par le prix du jeune écrivain de langue française ; il paraît en 1990 dans le recueil Villes d’exil et autres nouvelles, puis est réédité en 2000 par les Nouvelles éditions ivoiriennes. De 1993 à 2005, elle écrit pour Planète Jeunes, la Revue noire et Afrique magazine.'],
                ['p', 'Diplômée de la Fémis, elle réalise les courts métrages Le Génie d’Abou (1998) et Pour la nuit (2004), puis les documentaires La Coiffeuse de la rue Pétion (1999), L’Image, le vent et Gary Cooper (2001) et Documenta Opening Night (2002). Scénariste, elle collabore à Plus belle la vie et Seconde Chance, et co-écrit Arlit, deuxième Paris.'],
                ['h2', 'Trop noire pour être Française ?'],
                ['p', 'En 2015, elle réalise pour Arte le documentaire Trop noire pour être Française ?, qui mêle récit intime et témoignages d’historiens et de sociologues sur le regard porté sur les Français noirs. Deux ans plus tard, elle publie aux éditions Tallandier un récit autobiographique du même titre.'],
            ],
            'bibliography' => [
                ['title' => 'Isabelle Boni-Claverie', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Isabelle_Boni-Claverie'],
            ],
