                ['p', 'Jeanne de Cavally, née Jeanne Wawa et épouse Goba le 11 novembre 1926 à Bingerville, morte en 1992, est une écrivaine pour la jeunesse ivoirienne. Née dans une famille nombreuse, elle passe son enfance à Tabou puis à Abidjan et devient institutrice.'],
