            'deathPlace' => null,
            'occupations' => ['Écrivaine', 'Illustratrice', 'Conteuse'],
            'summary' => 'Écrivaine, illustratrice et conteuse ivoirienne née en 1967, Muriel Diallo a reçu le prix Saint-Exupéry 2012 pour Le Peintre maudit.',
            'blocks' => [
                ['p', 'Muriel Diallo, née le 19 mai 1967 à Boundiali, est une écrivaine ivoirienne autrice d’ouvrages pour enfants, artiste-peintre, illustratrice et conteuse. Diplômée des Beaux-Arts d’Abidjan, elle enseigne les arts plastiques au lycée pendant plusieurs années avant de se consacrer au conte et à l’écriture illustrée.'],
                ['h2', 'La littérature jeunesse'],
                ['p', 'Devenue conteuse et autrice de romans jeunesse, elle écrit en français, en moré et en wolof, et publie la série des Bibi n’aime pas… aux éditions Classiques ivoiriens. Installée à Paris, elle travaille aussi pour des maisons françaises, dont Vents d’Ailleurs et À dos d’âne, pour laquelle elle illustre une biographie de Nelson Mandela. Son livre Le Peintre maudit, paru en 2000, est sélectionné pour le prix Saint-Exupéry, qu’il remporte en 2012 dans la catégorie francophone.'],
                ['h2', 'Les oubliés de la jeunesse'],
                ['p', 'Ses récits abordent la drogue, la vie dans la rue, l’exil et les sécheresses du Sahel, et mettent souvent en scène des enfants orphelins livrés à eux-mêmes. Cette approche vise à sensibiliser les jeunes lecteurs et à donner une voix aux populations ignorées.'],
            ],
            'bibliography' => [
