            'blocks' => [
                ['p', 'Minlibé Grâce Ayémou, dite Grâce Minlibé, née le 17 janvier 1990, est une écrivaine, blogueuse et chroniqueuse littéraire ivoirienne. Passionnée de lecture dès l’enfance, elle s’oriente vers l’écriture à l’adolescence, d’abord à travers la poésie.'],
                ['h2', 'Le roman sentimental'],
                ['p', 'Elle publie plusieurs œuvres, dont le recueil Chimères de verre (2014) et le roman Tristesse au paradis, qui contribue à sa reconnaissance dans le paysage littéraire ivoirien. Son blog est consacré au roman sentimental, genre dont elle est une ardente supportrice et qu’elle fait découvrir à ses lecteurs.'],
