            'blocks' => [
                ['p', 'Flore Hazoumé, née en 1959 à Brazzaville, est une écrivaine ivoirienne, de père béninois et de mère congolaise. Elle est la fille d’Antoine Hazoumé, homme politique dahoméen et agent des services secrets français, et d’une mère congolaise, tante de l’homme politique Bernard Kolélas ; elle est aussi la petite-fille de l’écrivain Paul Hazoumé.'],
                ['h2', 'Entre l’Afrique et la France'],
                ['p', 'Elle passe une partie de son enfance et de sa scolarité en France. Elle écrit pour les adultes et pour les enfants, avec des histoires porteuses d’un message moral. En 2010, elle travaille avec Josette Abondio au magazine Scrib Spiritualité.'],
