        [
            'slug' => 'adjoua-flore-kouame',
            'name' => 'Adjoua Flore Kouamé',
            'fullName' => 'Adjoua Flore Kouamé',
            'birth' => '1964',
            'birthPlace' => 'Abidjan',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Écrivaine', 'Haute fonctionnaire'],
            'summary' => 'Romancière et haute fonctionnaire ivoirienne née en 1964, Adjoua Flore Kouamé a été la première Ivoirienne directrice de cabinet du vice-président de la République.',
            'blocks' => [
                ['p', 'Adjoua Flore Kouamé, née le 24 novembre 1964 à Abidjan, est une haute fonctionnaire de l’État de Côte d’Ivoire, administratrice civile et membre du corps préfectoral, également romancière de langue française. Diplômée de droit de l’École nationale d’administration de Côte d’Ivoire, elle est préfet hors grade.'],
                ['h2', 'Une carrière dans l’administration'],
                ['p', 'Dans les années 1990, elle devient administratrice civile et membre du bureau du ministère de l’Intérieur, où elle est successivement la première femme ivoirienne chef de cabinet, puis directrice de cabinet du ministre de l’Intérieur de 1991 à 1999. De 2000 à 2003, elle est secrétaire générale de la préfecture d’Abidjan, puis de celle d’Adzopé.'],
                ['p', 'Après un passage au ministère de l’Industrie et du Secteur privé comme cheffe de cabinet, elle est appelée au cabinet du Premier ministre comme conseillère spéciale en 2005, puis devient directrice de cabinet adjointe du Premier ministre jusqu’en 2017. Lorsque Daniel Kablan Duncan accède à la vice-présidence de la République, elle est la première Ivoirienne à occuper les fonctions de directrice de cabinet adjointe, puis de directrice de cabinet du vice-président. Elle assure aussi des vacations de cours à l’ENA d’Abidjan.'],
            ],
            'bibliography' => [
                ['title' => 'Adjoua Flore Kouamé', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Adjoua_Flore_Kouam%C3%A9'],
            ],
        ],
        [
            'slug' => 'agnes-kraidy',
            'name' => 'Agnès Kraidy',
            'fullName' => 'Agnès Kraidy',
            'birth' => '1965',
            'birthPlace' => 'Côte d’Ivoire',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Journaliste', 'Écrivaine'],
            'summary' => 'Journaliste et écrivaine ivoirienne née en 1965, Agnès Kraidy a dirigé la rédaction de Femme d’Afrique et de Fraternité Matin et préside le REFJPCI.',
            'blocks' => [
                ['p', 'Agnès Kraidy, née le 10 février 1965, est une écrivaine et journaliste ivoirienne. Elle a été rédactrice en chef du magazine Femme d’Afrique et du quotidien Fraternité Matin, et forme des journalistes depuis plus de vingt ans. Depuis le 24 juin 2025, elle est à la tête du conseil de gestion de l’Agence ivoirienne de presse.'],
                ['h2', 'Les livres'],
                ['p', 'Elle publie en 2004 son premier livre, Chroniques d’une guerre vaincue, compilation de ses éditoriaux consacrés à la crise politico-militaire. Suivent Une journaliste et un prêtre en dialogue sur l’Afrique, puis, en 2016, Tu me fous les boules ! Vaincre le cancer !, un livre-témoignage sur sa lutte contre le cancer du sein.'],
                ['p', 'Elle signe ensuite Les Affranchis du sort, recueil de vingt portraits de personnes ayant vaincu leur handicap, préfacé par l’ancien Premier ministre Amadou Gon Coulibaly, et cosigne avec Alex Kipré un livre consacré à Béatrice Abréma Kétouré, première femme ivoirienne à avoir obtenu un permis de conduire. Avec Zio Moussa, elle co-écrit en 2020 la biographie de Mathieu Kadio-Morokro.'],
            ],
            'bibliography' => [
                ['title' => 'Agnès Kraidy', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Agn%C3%A8s_Kraidy'],
            ],
        ],
        [
            'slug' => 'michelle-lora',
            'name' => 'Michelle Lora',
            'fullName' => 'Michelle Lora',
            'birth' => '1968',
            'birthPlace' => 'Bouaké',
            'death' => null,
            'deathPlace' => null,
            'occupations' => ['Écrivaine', 'Universitaire'],
            'summary' => 'Écrivaine et universitaire ivoirienne née en 1968, Michelle Lora est l’autrice d’une vingtaine-cinq livres de contes africains pour la jeunesse.',
            'blocks' => [
                ['p', 'Michelle Lora, née le 20 août 1968 à Bouaké, est une écrivaine et universitaire ivoirienne. Ancienne élève du lycée d’excellence Sainte-Marie de Cocody, où elle obtient son baccalauréat en 1987, elle poursuit des études ibériques en France et soutient en 1999 une thèse de doctorat intitulée La dynamique textuelle chez Alberto Insúa.'],
                ['h2', 'L’universitaire et la conteuse'],
                ['p', 'Enseignante-chercheuse à la faculté d’études ibériques et latino-américaines de l’université Félix-Houphouët-Boigny d’Abidjan, elle est maître-assistante et ancienne vice-doyenne chargée de la recherche de 2007 à 2009. Ses recherches portent sur la critique littéraire et génétique, les littératures espagnole et africaine et la communication sociale.'],
                ['p', 'Elle écrit uniquement des nouvelles pour enfants et affirme en 2022 compter vingt-cinq livres de contes africains jeunesse. Elle a mis sur pied une compagnie de conteurs pour enfants et les ateliers « Pathé Pathé ». Première vice-présidente de l’Association des écrivains de Côte d’Ivoire de 2012 à 2015, elle est aussi chroniqueuse radio sous le pseudonyme de « D Love ».'],
            ],
            'bibliography' => [
                ['title' => 'Michelle Lora', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Michelle_Lora'],
            ],
        ],
