            'blocks' => [
                ['p', 'Constance Toma’m Yaï, née le 9 décembre 1955 à Abidjan, est une féministe, autrice et femme politique ivoirienne. Elle grandit dans une famille progressiste qui élève filles et garçons dans une égalité de traitement ; sa grand-mère maternelle était une exciseuse reconnue dans tout l’ouest du pays.'],
                ['h2', 'Les droits des femmes'],
                ['p', 'Professeure spécialisée en rééducation des troubles du langage et consultante internationale sur les questions de parité, elle fonde en 1992 l’Association ivoirienne pour les droits des femmes (AIDF), l’une des premières organisations féministes du pays. L’AIDF œuvre pour l’égalité entre les sexes, milite pour l’application effective des lois en faveur des femmes et sensibilise à la situation des jeunes filles, en ville comme en milieu rural.'],
                ['p', 'Elle contribue également à la création du Comité national de lutte contre les pratiques traditionnelles néfastes. Elle succède à Agnès Monnet à la présidence de l’Agence ivoirienne de coopération francophone, poste qu’elle quitte en 2012. La Ligue ivoirienne des droits des femmes a inauguré en son honneur la « Bibliothèque Constance Yaï » à l’école primaire publique Rail 4, à Abobo.'],
            ],
            'bibliography' => [
                ['title' => 'Constance Yaï', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Constance_Ya%C3%AF'],
