                ['p', 'Abdoul Kader Keïta, né le 6 août 1981 à Abidjan, est un footballeur international ivoirien. Né d’un père malien et d’une mère ivoirienne, il passe son enfance à Gagnoa et se fait remarquer par son aisance balle au pied.'],
                ['h2', 'De l’Africa Sports au Golfe'],
                ['p', 'Il commence sa carrière professionnelle à l’Africa Sports National, avec lequel il remporte le championnat et la Coupe africaine des vainqueurs de coupe en 1999. Après un passage en Suède à l’IF Elfsborg, il joue à l’Étoile sportive du Sahel de 2000 à 2002, puis à Al-Aïn et à Al Sadd.'],
                ['h2', 'Lille et les Éléphants'],
                ['p', 'Suivi par de nombreux clubs européens, il choisit Lille en 2005 et s’y impose comme milieu offensif. Il dispute avec la Côte d’Ivoire la CAN 2002 au Mali, où il est considéré comme le meilleur joueur ivoirien du tournoi, puis la Coupe du monde 2006 en Allemagne.'],
