                ['p', 'Arouna Koné, né le 11 novembre 1983 à Anyama, est un footballeur international ivoirien qui évolue au poste d’attaquant. Il grandit dans une fratrie de neuf frères et cinq sœurs et apprend le football dans la rue.'],
                ['h2', 'Du Rio d’Anyama au Lierse'],
                ['p', 'Son père s’oppose d’abord à une carrière de footballeur et lui interdit de jouer en club. Après son décès, Arouna Koné rejoint le Rio d’Anyama avec l’accord de sa mère, arrête ses études secondaires à 16 ans et est repéré par le Lierse SK, où il devient professionnel en 2002.'],
                ['h2', 'Roda JC et la sélection'],
                ['p', 'Pour sa première saison au Lierse, il inscrit onze buts, puis rejoint le Roda JC pour un million d’euros. Il y marque onze buts lors de sa première saison et quinze lors de la deuxième, des performances qui lui ouvrent les portes de clubs plus prestigieux et de l’équipe nationale ivoirienne.'],
            ],
            'bibliography' => [
