            'blocks' => [
                ['p', 'N’dri Koffi Romaric Christian, né le 4 juin 1983 à Abidjan, est un footballeur international ivoirien. Milieu de terrain polyvalent, il peut jouer en position défensive, au centre du terrain ou en défense centrale.'],
                ['h2', 'Beveren et Le Mans'],
                ['p', 'Il commence sa carrière à l’ASEC Mimosas et signe au KSK Beveren en 2003. Lors de sa deuxième saison en Belgique, il marque 13 buts en 32 matchs et permet à son club d’éviter la relégation. En mai 2005, il s’engage avec Le Mans, où il reste trois saisons.'],
                ['h2', 'Séville et la sélection'],
                ['p', 'Le 21 mai 2008, il signe au FC Séville pour cinq ans, pour un montant estimé entre 8 et 10 millions d’euros, et y retrouve son compatriote Arouna Koné. Il prend sa retraite sportive le 1er janvier 2017, après un dernier club en Inde. Avec les Éléphants, il est finaliste de la CAN 2006 et participe à l’édition 2013.'],
            ],
            'bibliography' => [
                ['title' => 'Romaric', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Romaric_(football)'],
