                ['h2', 'Le choix des Éléphants'],
                ['p', 'En 2016, il opte pour la nationalité sportive ivoirienne après avoir porté à deux reprises le maillot de l’équipe d’Angleterre. Il dispute ensuite quatre Coupes d’Afrique des nations avec la Côte d’Ivoire.'],
