            'blocks' => [
                ['p', 'Sébastien Haller, né le 22 juin 1994 à Ris-Orangis, dans l’Essonne, est un footballeur international ivoirien qui joue au poste d’avant-centre. Il est le fils d’un père français et d’une mère ivoirienne, Simone Kuyo, et grandit à Vigneux-sur-Seine.'],
                ['h2', 'Auxerre et Utrecht'],
                ['p', 'Il commence le football au FCO Vigneux de 2003 à 2005, puis au CS Brétigny, avant d’intégrer à 13 ans le centre de formation de l’AJ Auxerre. Il signe son premier contrat professionnel le 26 juin 2011 et joue son premier match avec l’équipe première contre Nîmes. En manque de temps de jeu, il est prêté à Utrecht lors de l’hiver 2014-2015 et y inscrit un quadruplé le 15 février 2015.'],
                ['h2', 'Le héros de la CAN 2023'],
                ['p', 'Le 11 février 2024, il inscrit le but victorieux de la Côte d’Ivoire dans les dix dernières minutes de la finale de la Coupe d’Afrique des nations 2023 face au Nigeria. Ce titre conclut un parcours qui l’a conduit de l’AJ Auxerre à Utrecht, puis à la sélection ivoirienne.'],
            ],
