                ['p', 'Éric Bailly, né le 12 avril 1994 à Bingerville, est un footballeur international ivoirien qui évolue au poste de défenseur central. Il grandit au quartier de Koumassi Sicogi, dans la banlieue sud d’Abidjan, et est d’ethnie guéré.'],
                ['h2', 'Espanyol et Villarreal'],
                ['p', 'Détecté lors d’une compétition au Burkina Faso, il part en Espagne et est recruté par le RCD Espanyol en décembre 2011, où il fait ses débuts en Liga en octobre 2014. En février 2015, il rejoint Villarreal pour 5,7 millions d’euros et atteint les demi-finales de la Ligue Europa 2015-2016.'],
                ['h2', 'Manchester United'],
                ['p', 'Le 8 juin 2016, son transfert à Manchester United est officialisé pour 38 millions d’euros. Il y remporte la Community Shield dès ses débuts officiels et s’impose comme international ivoirien.'],
