                ['h2', 'Angers et Lille'],
                ['p', 'Il intègre Angers SCO en 2013, passe par l’équipe réserve, puis est prêté à l’US Orléans, avec lequel il termine vice-champion de National et est élu meilleur joueur de la saison 2015-2016. Il découvre ensuite la Ligue 1 avec Angers, puis rejoint le LOSC en 2017 pour dix millions d’euros et termine vice-champion de France en 2019.'],
                ['h2', 'Arsenal et Villarreal'],
                ['p', 'Ses performances le conduisent à Arsenal, puis à Villarreal, où il évolue comme ailier. Il porte également le maillot de la Côte d’Ivoire et participe aux compétitions internationales avec les Éléphants.'],
