            'birthPlace' => 'Abidjan',
            'death' => '1992',
            'deathPlace' => 'Atlanta (États-Unis)',
            'occupations' => ['Athlète'],
            'summary' => 'Athlète ivoirien (1963-1992), Gabriel Tiacoh, spécialiste du 400 m, est le premier médaillé olympique de la Côte d’Ivoire.',
            'blocks' => [
                ['p', 'Gabriel Tiacoh, né le 9 février 1963 à Abidjan et mort le 4 avril 1992 à Atlanta, est un athlète ivoirien spécialiste du 400 mètres. Issu d’une lignée de notables de Toumodi, il est le fils du docteur Kouadio Tiacoh Rémi Blaley, médecin gynécologue et membre fondateur du PDCI-RDA en 1946.'],
                ['h2', 'Los Angeles 1984'],
                ['p', 'Il commence l’athlétisme à 13 ans au Centre sportif municipal d’Épinay-sur-Seine, sous la direction de Pascal Zavaroni, et collectionne les titres de champion de France juniors et universitaires. En 1983, il part étudier à l’université de l’État de Washington et s’entraîne avec John Chaplin. Aux Jeux de Los Angeles, il court sa série en 45 s 15 et établit en demi-finale la meilleure performance mondiale de la saison en 44 s 64, avant de remporter la médaille d’argent.'],
                ['h2', 'Une carrière brève'],
                ['p', 'La même année, il gagne le 400 m et la médaille d’argent du relais 4 × 100 m aux championnats d’Afrique de Rabat. Sa carrière s’interrompt brutalement par sa mort à Atlanta en 1992, à 29 ans.'],
            ],
            'bibliography' => [
                ['title' => 'Gabriel Tiacoh', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Gabriel_Tiacoh'],
            ],
