            'summary' => 'Sprintrice ivoirienne née en 1988, Marie-Josée Ta Lou a été double vice-championne du monde du 100 m et du 200 m en 2017.',
            'blocks' => [
                ['p', 'Marie-Josée Ta Lou, épouse Smith, née le 18 novembre 1988 à Bouaflé, est une athlète ivoirienne spécialiste du sprint. Elle passe sa jeunesse à Koumassi, dans la banlieue d’Abidjan, où naît sa passion pour le football.'],
                ['h2', 'Des débuts pieds nus'],
                ['p', 'Son frère s’opposant à ce qu’elle intègre une équipe féminine de football, ses amis lui conseillent l’athlétisme. Lors d’un essai sur 200 m organisé par Florence Olonade, championne de Côte d’Ivoire du 100 m en 1988, elle court pieds nus et remporte la course face à des athlètes entraînées.'],
                ['h2', 'Londres 2017'],
                ['p', 'Grâce à une bourse sportive, elle étudie la médecine à l’université de Shanghai à partir de 2008, puis entre en 2014 à l’IAAF de Dakar, où elle progresse sous la direction d’Anthony Koffi. Elle atteint le niveau d’élite et devient vice-championne du monde du 100 mètres et du 200 mètres à Londres en 2017.'],
            ],
