            'blocks' => [
                ['p', 'Max Brito, né le 8 avril 1968 à Abidjan et mort le 19 décembre 2022 à Bordeaux, est un joueur ivoirien de rugby à XV. Il a deux frères, Patrick et Fabrice, eux aussi joueurs de rugby, et rejoint son père en France en 1972.'],
                ['h2', 'La Coupe du monde 1995'],
                ['p', 'Il commence le rugby au Biscarrosse olympique, dans les Landes, et refuse une proposition du CA Bègles pour rester dans son club formateur. Il ne devait pas participer à la Coupe du monde 1995 mais remplace son frère Patrick, forfait pour une pubalgie.'],
                ['h2', 'La blessure'],
                ['p', 'Trois minutes après le début du match Côte d’Ivoire-Tonga, il est plaqué par Inoke Afeaki avant que plusieurs joueurs ne lui tombent dessus. Transporté à l’hôpital Unitas de Pretoria, il est opéré des quatrième et cinquième vertèbres mais reste paralysé sous la nuque. Il vit ensuite à Talence, et une académie Max Brito ainsi qu’un challenge à son nom sont créés.'],
            ],
