            'summary' => 'Milieu international ivoirien né en 1997, Ibrahim Sangaré s’est révélé à Toulouse avant de s’imposer au PSV Eindhoven puis à Nottingham Forest.',
            'blocks' => [
                ['p', 'Ibrahim Sangaré, né le 2 décembre 1997 à Koumassi, est un footballeur international ivoirien qui évolue au poste de milieu de terrain. Il commence au Tout Puissant Koumassi, dans le sud d’Abidjan, avant de rejoindre l’AS Denguélé d’Odienné en 2012. En 2014, il est l’un des trois nommés pour le titre de meilleur espoir du championnat ivoirien.'],
                ['h2', 'Toulouse et le PSV'],
                ['p', 'En juillet 2016, il s’engage avec le Toulouse FC, où il débute le 22 octobre 2016 contre Angers et connaît sa première titularisation le 30 novembre contre Montpellier. Il prolonge jusqu’en 2021 en juin 2017 et marque son premier but en Ligue 1 le 24 février 2018 face à Monaco. Gêné par une rupture du tendon du gros orteil à l’automne 2018, il revient en janvier 2019. Le 28 septembre 2020, il rejoint le PSV Eindhoven pour neuf millions d’euros.'],
                ['h2', 'Nottingham Forest et les Éléphants'],
                ['p', 'Le 1er septembre 2023, il s’engage avec Nottingham Forest pour 30 millions d’euros. Avec la Côte d’Ivoire, il participe aux CAN 2019 et 2021, puis est retenu pour la CAN 2023, remportée à domicile par les Éléphants.'],
            ],
            'bibliography' => [
                ['title' => 'Ibrahim Sangaré', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Ibrahim_Sangar%C3%A9_(football,_1997)'],
