            'blocks' => [
                ['p', 'Odilon Kossounou, né le 4 janvier 2001 à Abidjan, est un footballeur international ivoirien qui évolue au poste de défenseur central. Formé à l’académie de l’ASEC Abidjan, il rejoint la Suède et le Hammarby IF en janvier 2019, peu après ses 18 ans, et joue son premier match d’Allsvenskan le 1er avril 2019 face à l’IF Elfsborg.'],
                ['h2', 'Bruges et Leverkusen'],
                ['p', 'Le 8 mai 2019, il s’engage pour quatre saisons avec le Club Bruges KV, dont il devient le premier joueur ivoirien. Il débute le 25 septembre 2019 en coupe de Belgique face aux Francs-Borains, puis découvre la Ligue des champions le 6 novembre 2019 contre le Paris SG. Le 22 juillet 2021, il rejoint le Bayer Leverkusen pour un contrat jusqu’en 2026.'],
                ['h2', 'L’Atalanta et la sélection'],
                ['p', 'Le 28 août 2024, il est prêté une saison à l’Atalanta Bergame, qui lève son option d’achat le 13 juin 2025. Avec les Éléphants, il participe aux CAN 2021 et 2025 et est retenu pour la CAN 2023, remportée par la Côte d’Ivoire.'],
            ],
            'bibliography' => [
                ['title' => 'Odilon Kossounou', 'publisher' => 'Wikipédia en français', 'year' => null, 'url' => 'https://fr.wikipedia.org/wiki/Odilon_Kossounou'],
