            'blocks' => [
                ['p', 'Emerse Faé, né le 24 janvier 1984 à Nantes, est un ancien footballeur international ivoirien, reconverti entraîneur. Formé au FC Nantes, il joue ensuite au Reading FC puis à l’OGC Nice, avant de mettre fin à sa carrière professionnelle le 1er février 2012, à cause de phlébites à répétition. Avec l’équipe de France des moins de 17 ans, il remporte la Coupe du monde 2001, puis il choisit de défendre les couleurs de la Côte d’Ivoire.'],
                ['h2', 'Quarante-quatre sélections'],
                ['p', 'Il compte 44 sélections et un but avec la sélection ivoirienne, dont il est finaliste de la Coupe d’Afrique des nations 2006.'],
                ['h2', 'Le sacre de 2024'],
                ['p', 'Après avoir entraîné les U19 de l’OGC Nice, puis la réserve du Clermont Foot de 2019 à 2022, il devient entraîneur adjoint de l’équipe nationale ivoirienne en 2022. Pendant la CAN 2023, il prend la tête des Éléphants après la démission de Jean-Louis Gasset et les mène au titre. Il devient ainsi le deuxième sélectionneur ivoirien à remporter la compétition, après Yéo Martial en 1992. Il obtient en 2025 le brevet d’entraîneur professionnel de football.'],
            ],
