                ['h2', 'Les Éléphants'],
                ['p', 'Il dispute son premier match avec la Côte d’Ivoire le 8 octobre 2020 face à la Belgique, puis son premier match officiel le 17 novembre 2020 contre Madagascar, en qualifications pour la CAN 2021.'],
