            'blocks' => [
                ['p', 'Bakari Shlomo Maurice Koné, dit « Baky », né le 17 septembre 1981 à Abidjan, est un footballeur international ivoirien qui évolue au poste d’attaquant. Repéré par Jean-Marc Guillou à l’âge de 12 ans, il intègre la première promotion de l’Académie Mimo Sifcom, le centre de formation de l’ASEC Abidjan. Il y gagne trois titres de champion de Côte d’Ivoire et une Supercoupe d’Afrique en 1999, puis est transféré en 2002 au club qatari d’Al Ittihad, où il reste six mois.'],
                ['h2', 'Lorient, Nice et Marseille'],
                ['p', 'En 2003, il rejoint le FC Lorient, alors en Ligue 2, avant de s’engager avec l’OGC Nice en 2005, puis avec l’Olympique de Marseille en 2008. Il est champion de France avec l’OM en 2010.'],
                ['h2', 'La CAN 2006'],
                ['p', 'À 24 ans, il emmène les Éléphants jusqu’en finale de la CAN 2006, perdue face à l’Égypte, pays hôte. Il est l’un des artisans du parcours ivoirien dans la compétition.'],
