            'blocks' => [
                ['p', 'Guy Roland Demel, né le 13 juin 1981 à Orsay, est un footballeur international ivoirien, reconverti entraîneur. Né en Île-de-France de parents ivoiriens, il grandit à Marseille et est le demi-frère des footballeurs Yannick Sagbo et Igor Late-Yedo. Repéré par Arsène Wenger à Arsenal, il choisit finalement de s’engager avec le Borussia Dortmund.'],
                ['h2', 'Hambourg et West Ham'],
                ['p', 'Après Dortmund, il rejoint le Hambourg SV, où il est titulaire dans une défense qui figure parmi les meilleures de Bundesliga lors de la saison 2005-2006. Il termine ensuite sa carrière en Angleterre, à West Ham United, alors en Championship.'],
                ['h2', 'Les Éléphants'],
                ['p', 'Malgré plusieurs convocations en équipe de France espoirs, il choisit la Côte d’Ivoire, avec laquelle il obtient pour la première fois la qualification pour la Coupe du monde 2006, en éliminant le Cameroun et l’Égypte. Il fait partie des 23 Ivoiriens retenus pour le Mondial 2010 et compte 35 sélections. Il est aujourd’hui sélectionneur adjoint de la Côte d’Ivoire.'],
