                ['p', 'Bonaventure Kalou, né le 12 janvier 1978 à Oumé, est un footballeur international ivoirien qui évoluait au poste d’attaquant. Il est le frère aîné de Salomon Kalou. Il se fait remarquer aux Pays-Bas, au Feyenoord Rotterdam, avec lequel il remporte la Coupe de l’UEFA en 2002.'],
