                ['h2', 'Lens et Vavoua'],
                ['p', 'Fin juillet 2007, il rejoint le RC Lens pour 1,5 million d’euros et retrouve Guy Roux. En octobre 2018, il est élu maire de Vavoua, ville du centre de la Côte d’Ivoire.'],
