                ['h2', 'La CAN 1992'],
                ['p', 'Avec la Côte d’Ivoire, il compte 44 sélections et 25 buts. Il remporte la CAN 1992 et termine deuxième meilleur buteur de l’édition 1994, avec quatre réalisations, derrière le Nigérian Rashidi Yekini. Il participe également aux CAN 1996 et 1998.'],
