                ['p', 'Saint-Joseph Gadji Celi, né le 1er mai 1961, est un ancien footballeur international ivoirien devenu chanteur. Sa carrière commence en 1980 au Stella Club d’Adjamé, où il passe deux saisons avant de rejoindre l’ASEC Abidjan en 1983. En 1986, il tente une aventure en France, au FC Sète, en deuxième division, où il reste trois saisons, avant de revenir à l’ASEC en 1989.'],
                ['h2', 'Le capitaine de 1992'],
                ['p', 'Il s’illustre en sélection nationale de 1984 à 1992. Capitaine des Éléphants, il mène la Côte d’Ivoire à sa première victoire en Coupe d’Afrique des nations, en 1992 au Sénégal.'],
                ['h2', 'La chanson des Éléphants'],
                ['p', 'Passionné de musique, il commence à chanter en 1986 pour soutenir l’équipe nationale et compose plusieurs titres pour les CAN : « Allez les éléphants 1 » au Caire en 1986, puis les éditions de 1988, 1990 et 1992. En 1989, il rend hommage à son club avec « Et Dieu créa l’ASEC ». Après sa carrière, il préside le conseil d’administration du Bureau ivoirien du droit d’auteur et devient le premier président de l’Union nationale des artistes de Côte d’Ivoire. En août 2023, il est nommé ambassadeur de la Fédération ivoirienne de football.'],
            ],
