                ['p', 'Lassina Dao, né le 6 février 1971, est un ancien footballeur international ivoirien. Défenseur polyvalent réputé pour son pied gauche, il évolue à l’ASC Bouaké, à l’ASEC Mimosas, à l’Africa Sports d’Abidjan et à Al Ittihad Tripoli, en première division libyenne. Son surnom, « Pecto », accompagne sa réputation de buteur sur coups de pied arrêtés.'],
