            'summary' => 'Attaquant international ivoirien né en 1976, Ibrahima Bakayoko a été capitaine des Éléphants et a joué à Montpellier, Everton et l’Olympique de Marseille.',
            'blocks' => [
                ['p', 'Ibrahima Bakayoko, né le 31 décembre 1976 à Séguéla, est un ancien footballeur international ivoirien qui évoluait au poste d’attaquant. Arrivé en Europe en 1995 après un essai non concluant à Sion, il est repéré par Roger Milla, alors recruteur pour le Montpellier HSC, lors d’un match contre l’ASEC Abidjan. Il gagne la Coupe Gambardella en 1996 après avoir débuté en première division, et se distingue notamment par un triplé inscrit en moins de quinze minutes à Lille.'],
                ['h2', 'Everton et Marseille'],
                ['p', 'Il rejoint ensuite Everton, pour 45 millions de francs, mais n’y reste qu’une saison, avec quatre buts en 23 matchs. En juin 1999, il s’engage avec l’Olympique de Marseille pour 40 millions de francs. Capitaine des Éléphants, il vit à Marseille un parcours irrégulier, souvent décrit comme capable du meilleur comme du pire. À partir d’août 2003, il poursuit sa carrière à Osasuna, Istres, Livourne et Messine.'],
            ],
            'bibliography' => [
