                ['p', 'Cyril Domoraud, né le 22 juillet 1971 à Lakota, est un ancien footballeur international ivoirien et ancien capitaine de l’équipe nationale. Il est le frère de Gilles et de Jean-Jacques Domoraud, également footballeurs. Il joue à Noiseau, Sucy-en-Brie et Créteil, puis au Red Star, aux Girondins de Bordeaux, à l’Olympique de Marseille, à l’Inter Milan, à Bastia, à l’AS Monaco, à l’Espanyol Barcelone et à Konyaspor.'],
