                ['h2', 'La CAN 2014 et le Mondial'],
                ['p', 'Appelée en équipe de Côte d’Ivoire en décembre 2011, elle dispute le championnat d’Afrique 2012, la première compétition continentale du pays. Lors de l’édition 2014, elle inscrit le but décisif de la victoire 1 à 0 face à l’Afrique du Sud, dans le match pour la troisième place, qui qualifie la Côte d’Ivoire pour sa toute première Coupe du monde. Au Mondial 2015, elle joue trois matchs, contre l’Allemagne, la Thaïlande et la Norvège.'],
