                ['p', 'Rosemonde Kouassi, née le 26 décembre 2001, est une footballeuse internationale ivoirienne qui évolue au poste d’attaquante. En 2019, elle tente une première expérience à l’étranger, à l’Hapoël Ra’anana, en Israël, avec trois buts lors de ses deux premiers matchs, avant de rentrer en Côte d’Ivoire. Elle signe alors avec l’Africa Sports en novembre 2020, remporte le championnat ivoirien 2020-2021 et est sacrée meilleure joueuse de la saison.'],
                ['h2', 'Fleury 91 et la sélection'],
                ['p', 'En novembre 2021, elle s’engage avec sa compatriote Mariam Diakité au FC Fleury 91, en première division française, où elle signe son premier contrat professionnel. Elle marque dès le 13 novembre 2021 face à l’ASSE, est élue deux fois joueuse du mois, meilleure espoir de la saison 2021-2022 et figure dans l’équipe-type de D1. Elle est aussi sacrée meilleure joueuse ivoirienne à l’étranger et prolonge jusqu’en 2025. Avec les Élephants, elle brille lors du tournoi de l’UFOA-B en 2019. Elle évolue aujourd’hui au Washington Spirit.'],
