            'blocks' => [
                ['p', 'Seydou Gbané, né le 12 avril 1992 en Côte d’Ivoire, est un taekwondoïste ivoirien. Il est le frère des taekwondoïstes Abdoulaye et Hamza Gbané. Il remporte la médaille de bronze des moins de 87 kg aux Jeux africains de 2015 à Brazzaville, puis l’or dans la même catégorie aux Jeux africains de 2019 à Rabat.'],
                ['h2', 'Championnats d’Afrique et Jeux olympiques'],
                ['p', 'Il est champion d’Afrique des moins de 87 kg en 2012 à Antananarivo, en 2014 à Tunis et en 2018 à Agadir, médaillé d’argent en 2009 et 2016, et de bronze en 2010 et 2021. Il participe aux Championnats du monde 2019 à Manchester, puis aux Jeux olympiques de Tokyo, en 2021, dans la catégorie des plus de 80 kg.'],
            ],
            'bibliography' => [
