                ['p', 'Aaron François Kobenan, né le 12 août 1998 en Côte d’Ivoire, est un taekwondoïste ivoirien. Aux Championnats d’Afrique, il est médaillé d’argent chez les juniors en 2014 à Gaborone, puis chez les seniors en 2021 à Dakar et en 2023 à Abidjan, et champion en 2022 à Kigali.'],
                ['h2', 'Jeux africains et opens'],
