                ['h2', 'Championnats et records'],
                ['p', 'Il atteint les demi-finales des Championnats d’Afrique 2002, des Jeux panafricains 2003, des Championnats d’Afrique 2006 et des Jeux africains 2007, et dispute la finale du 100 mètres des Championnats d’Afrique 2004 à Dakar. Avec le relais 4 × 100 mètres, il termine quatrième aux Jeux de la Francophonie 2009. Ses records personnels sont de 10 s 43 sur 100 mètres, réalisé à Dakar, et 21 s 01 sur 200 mètres, à Niamey en décembre 2005.'],
