                ['p', 'Paul Fernand Kra Koffi est un athlète paralympique ivoirien qui concourt généralement dans les épreuves de demi-fond de catégorie T12. Il est malvoyant. Il prend part aux Jeux paralympiques d’été de 2000 à Sydney, en Australie, où il est engagé sur le 1 500 mètres et le 400 mètres, mais c’est sur le 800 mètres qu’il décroche la médaille de bronze pour la Côte d’Ivoire.'],
